    Determines whether the tile at (`index_i`, `index_j`) is occupied.

    Args:
        index_i (int):
            Row index.
        index_j (int):
            Column index.
        tile_arrangement (List[List[str]]):
            Arrangement of the tiles as a 2D grid.

    Returns:
        bool:
            Whether or not the tile is occupied.
    """
def is_occupied(index_i: Any, index_j: Any, tile_arrangement: Any) -> object {
    if not (0 <= index_i <= (len(tile_arrangement) - 1)) {
        raise IndexError;
    }
    if not (0 <= index_j <= (len(tile_arrangement[0]) - 1)) {
        raise IndexError;
    }
    if (tile_arrangement[index_i][index_j] == "#") {
        return True;
    } else {
        return False;
    }
}

"""
    Reverse a hex string, bf99 -> 99bf
    """
def hex_reverse(integer: Any, size: Any) -> object {
    string = '{0:0{1}x}'.format(integer, size);
    return ''.join([string[(i - 2):i] for i in range(len(string), 0, -2)]);
}

